// Browser-local simulated assistant. No model or external service receives data.
(()=>{let owner='',messages=[],draft=null,pendingNav=null;const root=document.createElement('div');root.id='assistantRoot';document.body.append(root);const actions=[['Apply leave','Leave'],['Request overtime','Overtime'],['Correct attendance','Attendance correction'],['Submit claim','Claim'],['Request certificate','Certificate'],['Ask HR / Finance','Helpdesk']];
function sync(){if(owner!==self()){owner=self();messages=[];draft=null;pendingNav=null}return owner}
function paint(){sync();
/* A new joiner is offered the assistant once, then it waits in the corner. */
const joining=typeof joinerCaseFor==='function'?joinerCaseFor(self()):null;
const within=joining&&typeof joiningDaysLeft==='function'&&joiningDaysLeft(joining)>0;
let greeted=false;try{greeted=localStorage.getItem('samanvay-joiner-greeted')===self()}catch{}
if(within&&!greeted){try{localStorage.setItem('samanvay-joiner-greeted',self())}catch{}
root.innerHTML=`<section class="ask-welcome" role="dialog" aria-label="Welcome"><button class="ask-welcome-close" onclick="DemoAssistant.dismiss()" aria-label="Close">×</button><strong>Welcome to NRL, ${esc(joining.name.split(' ')[0])}.</strong><p>I can explain your joining date, your location, leave, pay and anything else in the portal. I will stay in the corner for your first 30 days.</p><div class="ask-welcome-actions"><button class="primary" onclick="DemoAssistant.open()">Ask a question</button><button onclick="DemoAssistant.dismiss()">Not now</button></div></section>`;return}
root.innerHTML=`<button class="ask-launch" onclick="DemoAssistant.open()">✦ Ask Samanvay</button>`}
function open(){sync();root.innerHTML=`<section class="ask-panel" role="dialog" aria-modal="false" aria-label="Ask Samanvay"><header><div><strong>✦ Ask Samanvay</strong><small>HR & Finance companion · Demo</small></div><button aria-label="Close assistant" onclick="DemoAssistant.close()">×</button></header><div class="ask-scope">${esc(person().name)} · Own records + professional reporting links<br>Powered by Gemini · Fictional demo records</div><div class="ask-log" role="log" aria-live="polite">${messages.length?messages.map(m=>`<article class="ask-${m.who}"><small>${m.who==='user'?'You':'Samanvay'}</small><p>${esc(m.text)}</p>${m.nav?`<button onclick="DemoAssistant.navigate('${m.nav}')">${esc(m.label)} →</button>`:''}${m.action?`<button onclick="DemoAssistant.action('${m.action}')">Review ${esc(m.action)} request →</button>`:''}</article>`).join(''):'<article><h3>How can I help today?</h3><p>Ask about leave balances, pay, claims, requests, or your reporting manager. I can also help prepare a request.</p></article>'}</div><button onclick="DemoAssistant.access()">What can I access?</button><button onclick="DemoAssistant.references()">HR & Finance reference library ↗</button><div class="ask-chips">${['My leave balance','My requests','Explain my salary','My reporting manager','Who reports to me?',...actions.map(a=>a[0])].map(a=>`<button onclick="DemoAssistant.ask(this.textContent)">${a}</button>`).join('')}</div><form onsubmit="DemoAssistant.send(event)"><label class="sr-only" for="askInput">Ask HR or Finance</label><input id="askInput" required maxlength="1000" placeholder="English, हिंदी या Hinglish mein poochhiye…"><button type="submit">Send</button></form><footer>Review details before submitting. Existing approvals and leave checks apply.</footer></section>`;root.querySelector('.ask-log').scrollTop=999999;root.querySelector('#askInput').focus()}
const destinations=[
{id:'salary',match:/salary|payslip|pay statement|वेतन|सैलरी|तनख्वाह|tankhwa|pagar/i,path:'Pay & Benefits → My pay statements → View statement',label:'Open my salary details',hi:'वेतन विवरण खोलें',hing:'Meri salary details kholiye'},
{id:'leave',match:/leave|chh?utt?i|छुट्टी|अवकाश/i,path:'Home → Quick actions → Apply leave, or Time & Workforce → Leave → Apply for leave',label:'Open the leave application',hi:'छुट्टी का आवेदन खोलें',hing:'Leave application kholiye'},
{id:'overtime',match:/overtime|extra hours|\bot\b|ओवरटाइम/i,path:'Time & Workforce → Overtime → Request overtime',label:'Open overtime request',hi:'ओवरटाइम अनुरोध खोलें',hing:'Overtime request kholiye'},
{id:'attendance',match:/attendance|punch|haziri|hajiri|उपस्थिति|हाजिरी/i,path:'Time & Workforce → Attendance → Request correction',label:'Open attendance',hi:'उपस्थिति खोलें',hing:'Attendance kholiye'},
{id:'claim',match:/claim|expense|reimburse|kharch|प्रतिपूर्ति|खर्च/i,path:'Pay & Benefits → Claims & reimbursements → ＋ Claim',label:'Open claims',hi:'दावे खोलें',hing:'Claims kholiye'},
{id:'certificate',match:/certificate|प्रमाणपत्र/i,path:'Employee Services → Service certificate → Start request',label:'Open certificate request',hi:'प्रमाणपत्र अनुरोध खोलें',hing:'Certificate request kholiye'},
{id:'hierarchy',match:/manager|hierarchy|reporting|boss|प्रबंधक/i,path:'User account → View profile → Reporting hierarchy',label:'Open reporting hierarchy',hi:'रिपोर्टिंग पदानुक्रम खोलें',hing:'Reporting hierarchy kholiye'},
{id:'profile',match:/profile|contact|address|प्रोफ़ाइल|पता/i,path:'User account → View profile → Personal information',label:'Open my profile',hi:'मेरी प्रोफ़ाइल खोलें',hing:'Meri profile kholiye'},
{id:'requests',match:/request|status|track|अनुरोध|स्थिति/i,path:'My Work → choose a status tab → Open the request',label:'Open My Work',hi:'मेरे कार्य खोलें',hing:'My Work kholiye'},
{id:'learning',match:/learning|training|course|प्रशिक्षण/i,path:'Performance & Learning → Assigned learning',label:'Open learning',hi:'प्रशिक्षण खोलें',hing:'Learning kholiye'},
{id:'help',match:/help|support|hr|finance|policy|नीति|मदद/i,path:'Employee Services → HR helpdesk → Start request; public references are in the assistant’s HR & Finance reference library',label:'Open employee services',hi:'कर्मचारी सेवाएँ खोलें',hing:'Employee services kholiye'}];
function handleNavigation(q){const raw=q.trim().toLowerCase();if(pendingNav&&/^(yes|yes please|please do|show me|open it|haan|han|ha|ji|हाँ|हां|जी)[.! ]*$/.test(raw)){const id=pendingNav;pendingNav=null;messages.push({who:'assistant',text:'Opening the requested screen. No request has been submitted.'});navigate(id);return true}if(pendingNav&&/^(no|no thanks|nahi|nahin|नहीं)[.! ]*$/.test(raw)){pendingNav=null;messages.push({who:'assistant',text:'Okay. You can follow the steps above whenever you are ready.'});open();return true}
const guide=/\b(where|how|navigate|find|kahan|kahaan|kidhar|kaise)\b|कहाँ|कहां|कैसे/i.test(q);if(!guide){pendingNav=null;return false}const destination=destinations.find(d=>d.match.test(q));if(!destination)return false;pendingNav=destination.id;const hi=/[\u0900-\u097f]/.test(q),hing=/\b(kahan|kahaan|kaise|kidhar|meri|mera|mujhe)\b/i.test(q);const text=hi?'पोर्टल में यह क्रम अपनाएँ:\n'+destination.path+'\n\nक्या आप चाहते हैं कि मैं संबंधित पेज या फ़ॉर्म खोल दूँ?':hing?'Portal mein yeh steps follow kijiye:\n'+destination.path+'\n\nKya main aapke liye yeh page ya form khol doon?':'Here is where to find it in the portal:\n'+destination.path+'\n\n'+(destination.id==='salary'?'Would you like to see your salary details now?':'Would you like me to open this page or form for you?');messages.push({who:'assistant',text,nav:destination.id,label:hi?destination.hi:hing?destination.hing:destination.label});open();return true}
function navigate(id){if(!destinations.some(d=>d.id===id))return;pendingNav=null;paint();switch(id){case'salary':go('Pay & Benefits');payslip();break;case'leave':requestForm('Leave');break;case'overtime':go('Time & Workforce');tab='Overtime';render();break;case'attendance':go('Time & Workforce');tab='Attendance';render();break;case'claim':go('Pay & Benefits');break;case'certificate':requestForm('Certificate');break;case'hierarchy':navigateProfile('hierarchy');break;case'profile':navigateProfile('personal');break;case'requests':go('My Work');break;case'learning':go('Performance & Learning');break;case'help':go('Employee Services');break}}
function extractDraft(q,type){const d={type,raw:q},normal=q.replace(/[०-९]/g,c=>String('०१२३४५६७८९'.indexOf(c)));const dates=normal.match(/\b\d{4}-\d{2}-\d{2}\b/g)||[];if(type==='Leave'){d.from=dates[0]||'';d.to=dates[1]||dates[0]||'';const kinds=[['casual','casual'],['sick','sick'],['annual','annual'],['floater','floater'],['बीमार','sick']];d.leaveType=kinds.find(([word])=>q.toLowerCase().includes(word))?.[1]||''}else d.dutyDate=dates[0]||'';const hours=normal.match(/(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|ghant[ae]|घंटे|घंटा)/i);if(hours)d.hours=hours[1];const amount=normal.match(/(?:₹|rs\.?|inr)\s*(\d+)/i);if(amount)d.amount=amount[1];const reason=q.match(/(?:because|reason\s*[:=]?|kyunki|क्योंकि|कारण\s*[:=]?)\s*(.+)/i);d.reason=reason?reason[1].trim():'';return d}
function references(){modal('HR & Finance reference library',`<div class="callout">Public reference sources are examples for evaluation, not adopted NRL policy. Company entitlements remain the portal’s fictional demo configuration.</div><h3>Public HR reference</h3><p>DoPT CCS Leave FAQs, updated 30 August 2022: covers general leave entitlement and leave encashment questions. Applicability and subsequent amendments require verification.</p><a href="https://documents.doptcirculars.nic.in/D2/D02est/RevisedFAQsFINAL12sgf.pdf" target="_blank" rel="noopener">Read official DoPT FAQ PDF ↗</a><h3>Public finance reference directory</h3><p>Department of Expenditure circulars: travelling allowance, transport allowance, HRA, pay and related topics. This is a source directory, not an imported policy corpus.</p><a href="https://doe.gov.in/en/orders-circulars" target="_blank" rel="noopener">Browse official finance circulars ↗</a><h3>Fictional Samanvay operating guide</h3><p>Leave: calendar-day requests are checked against selected-type balances and overlap. Pending requests reserve days. Approval deducts the balance.</p><p>Overtime: provide duty date, additional hours and work justification; review is required. Approval does not automatically calculate or pay overtime.</p><p>Claims: enter expense date, amount and reason. A reviewer decision does not establish payment. Attachments store filenames only.</p><p>Payroll: sample statement only; deductions are not a statutory computation.</p>`,btn('Close',"$('#dialog').close()"))}
function interpret(q){let text=q.normalize('NFKC').toLowerCase();const hindi=/[\u0900-\u097f]/.test(text),hinglish=/\b(meri|mera|mere|mujhe|mujko|kitni|kitna|kaise|chahiye|chaiye|karna|karo|hai|hain|batao|btao|chutti|chhutti|paisa|paise|tankhwa|tankhwah)\b/.test(text);const rules=[[/छुट्टी|छुट्टियां|अवकाश|\b(chh?utt?i|chhuttiyan|chuttiyan)\b/g,' leave '],[/ओवरटाइम|अतिरिक्त घंटे|\b(ot|over time|extra kaam|jyada kaam)\b/g,' overtime '],[/उपस्थिति|हाजिरी|हाज़िरी|\b(hajiri|haziri|attendance)\b/g,' attendance '],[/वेतन|तनख्वाह|सैलरी|कटौती|\b(tankhwa[h]?|salary|pagar|paisa|paise|katoti)\b/g,' salary '],[/प्रतिपूर्ति|खर्च|रिइम्बर्समेंट|\b(kharch[a]?|reimbursement|claim)\b/g,' claim '],[/प्रमाणपत्र|प्रमाण पत्र|\b(praman patra|certificate)\b/g,' certificate '],[/प्रबंधक|रिपोर्टिंग|किसको रिपोर्ट|\b(kisko report|kis ko report|boss|manager)\b/g,' manager '],[/नियम|नीति|पात्रता|\b(niyam|neeti|niti|policy|eligibility)\b/g,' policy '],[/शेष|बाकी|बची|बचा|कितनी|कितना|\b(bachi|bacha|baki|baaki|kitni|kitna|balance)\b/g,' balance '],[/स्थिति|कहाँ पहुंचा|कहां पहुंचा|मंजूर|\b(sthiti|status|kahan pahuncha|approve hua|manzoor)\b/g,' status '],[/आवेदन|चाहिए|करना है|कर दो|भेज दो|\b(chahiye|chaiye|karna|karo|kar do|bhej do|apply|submit)\b/g,' apply ']];for(const [pattern,replacement] of rules)text=text.replace(pattern,replacement);if(/status/.test(text))text='status';else if(/policy/.test(text))text='policy';else if(/balance/.test(text)&&/leave/.test(text))text='leave balance';return {text,hindi,hinglish}}
function scriptedAsk(q){sync();messages.push({who:'user',text:q});if(handleNavigation(q))return;const parsed=interpret(q),t=parsed.text;let text='',action='';const rule=actions.find(([label])=>t===label.toLowerCase());if(rule)action=rule[1];else if(/apply|request|submit|book|आवेदन|चाहिए/.test(t)){if(/overtime|extra hours|ओवरटाइम/.test(t))action='Overtime';else if(/leave|छुट्टी/.test(t))action='Leave';else if(/claim|reimburse|expense|प्रतिपूर्ति/.test(t))action='Claim';else if(/attendance|punch|उपस्थिति/.test(t))action='Attendance correction';else if(/certificate|प्रमाण/.test(t))action='Certificate'}
if(!action&&draft&&(/\d{4}-\d{2}-\d{2}|hours|ghante|घंटे|because|kyunki|reason/i.test(q))){action=draft.type;q=draft.raw+' '+q}if(action){draft=extractDraft(q,action);text='I can prepare your '+action+' request. Open the review form below, choose the dates and details, then Save draft or Submit request. Your request will follow the existing approval workflow. I have not submitted anything. Recognised details: '+JSON.stringify(Object.fromEntries(Object.entries(draft).filter(([k])=>k!=='raw')))+'. Missing or ambiguous values stay blank for review.';}
else if(/leave|balance|छुट्टी|शेष/.test(t)){text=window.LeaveModel.types.filter(x=>x.mode!=='allowance').map(x=>x.name+': '+leaveBalanceLabel(leaveEntry(self(),x.id))).join('\n')+'\n\nSource: your current demo leave ledger. Pending requests reserve days; approval deducts the selected balance. Calendar days are counted. These are sample entitlements, not official NRL rules.';}
else if(/salary|pay|deduct|वेतन|वित्त/.test(t)){text=role==='Contractor administrator'?'PSU employee payslips do not apply to this agency-worker demo. Ask your agency payroll team; I can help prepare a Helpdesk request.':'Sample monthly statement: Basic ₹54,000 + allowances ₹26,000 − deductions ₹10,600 = net ₹69,400. Source: portal demonstration pay statement. No deduction breakdown or real payroll is available, so I cannot explain a specific deduction or month-to-month change. Use a Helpdesk request for clarification.';}
else if(/manager|report|hierarchy|प्रबंधक/.test(t))text='Your reporting officer is '+hierarchyManagerName(self())+'. Explore My Profile → Reporting hierarchy for the full chain and direct reports. Source: fictional reporting assignments.';
else if(/request|status|claim|अनुरोध/.test(t)){const rs=state.requests.filter(r=>r.person===self());text=rs.length?rs.slice(0,10).map(r=>r.id+' · '+r.type+' · '+r.status+' · '+r.owner).join('\n')+'\nSource: your current browser-local requests. Open My Work for full history. Claim approval does not establish payment; payment tracking is not connected.':'You have no requests in this browser. I can help prepare leave, overtime, attendance correction, claims, certificates or helpdesk requests.';}
else if(/policy|eligible|benefit|नियम|नीति/.test(t))text='Demo rules: maximum '+state.policies.leave+' calendar days per leave request; selected-type balance and overlapping leave are checked. Overtime requires review and does not automatically generate pay. Claims require review and do not initiate payment. Source: current demo configuration. Official benefit and eligibility documents are not loaded; ask HR for an authoritative answer.';
else if(/hindi|हिंदी/.test(t))text='Use the Hindi language button in the portal header for translated screens and request forms. This demo recognises selected Hindi query terms; Hindi and Hinglish phrases are supported for demo topics; unrestricted conversation requires a connected language model.';
else text='I can check your leave balances and request status, explain the sample payslip, identify your manager, and prepare leave, overtime, attendance, claim, certificate or helpdesk requests. Official tax advice, real payment status and company policy documents are not available in this demo. Choose a suggestion or ask HR through a Helpdesk request.';
if(parsed.hindi||parsed.hinglish){const h=parsed.hindi;const intro=action?(h?'नीचे दिए बटन से अनुरोध फ़ॉर्म खोलें। तारीख, घंटे और विवरण जाँचकर ड्राफ्ट सहेजें या जमा करें। अभी कोई अनुरोध जमा नहीं हुआ है।':'Neeche button se request form kholiye. Dates, hours aur details check karke draft save ya submit kijiye. Abhi koi request submit nahi hui hai.'):/leave|balance/.test(t)?(h?'आपकी उपलब्ध छुट्टियों का विवरण नीचे है। लंबित अनुरोधों के दिन आरक्षित हैं।':'Aapki available chhuttiyon ka balance neeche hai. Pending requests ke din reserved hain.'):/salary/.test(t)?(h?'यह केवल नमूना वेतन विवरण है, वास्तविक भुगतान या कटौती का प्रमाण नहीं।':'Yeh sirf sample salary hai. Asli payment ya deduction ka record connected nahi hai.'):/manager/.test(t)?(h?'आपके रिपोर्टिंग अधिकारी: ':'Aapke reporting manager: ')+hierarchyManagerName(self()):/status/.test(t)?(h?'आपके अनुरोधों की वर्तमान स्थिति:':'Aapki requests ka current status:'):/policy/.test(t)?(h?'ये डेमो नियम हैं। आधिकारिक नियमों की पुष्टि HR से करें।':'Yeh demo rules hain. Official policy HR se confirm kijiye.'):(h?'मैं छुट्टी, वेतन, अनुरोध की स्थिति और HR फ़ॉर्म में मदद कर सकता हूँ।':'Main chhutti, salary, request status aur HR forms mein madad kar sakta hoon.');text=intro+'\n\n'+text;}messages.push({who:'assistant',text,action});open()}
function assistantHierarchy(){const nodes=hierarchyNodes(),lookup=new Map(nodes.map(n=>[n.id,n])),brief=n=>({id:n.id,name:n.name,designation:n.job,department:n.dept});const chain=[],seen=new Set([self()]);let id=hierarchyManagers[self()];while(id&&!seen.has(id)){seen.add(id);const n=lookup.get(id);if(!n)break;chain.push(brief(n));id=hierarchyManagers[id]}const direct=nodes.filter(n=>hierarchyManagers[n.id]===self()).map(brief);const descendants=[],queue=direct.map(n=>({...n,depth:1})),visited=new Set([self()]);while(queue.length){const n=queue.shift();if(visited.has(n.id))continue;visited.add(n.id);descendants.push(n);for(const child of nodes.filter(x=>hierarchyManagers[x.id]===n.id))queue.push({...brief(child),depth:n.depth+1})}return {source:'Portal fictional reporting assignments; not official NRL hierarchy',directReports:direct,reportingChain:chain,allReports:descendants,directReportCount:direct.length,totalReportCount:descendants.length}}
let aiBusy=false;
async function ask(q){sync();if(aiBusy)return;const employee=self();messages.push({who:'user',text:q});aiBusy=true;messages.push({who:'assistant',text:'Thinking…'});open();try{const context={hierarchy:assistantHierarchy(),today:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}),employee:{id:self(),name:person().name,role,manager:hierarchyManagerName(self())},leave:window.LeaveModel.types.filter(t=>t.mode!=='allowance').map(t=>({type:t.id,balance:leaveBalanceLabel(leaveEntry(self(),t.id))})),requests:state.requests.filter(r=>r.person===self()).slice(0,10).map(r=>({id:r.id,type:r.type,status:r.status,owner:r.owner})),samplePay:role==='Contractor administrator'?null:{basic:54000,allowances:26000,deductions:10600,net:69400}};const response=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:messages.slice(0,-1).map(m=>({role:m.who==='user'?'user':'assistant',content:m.text})),context})});const result=await response.json();if(employee!==self())return;messages.pop();if(!response.ok)throw new Error(result.error||'AI unavailable');const entry={who:'assistant',text:result.answer};if(destinations.some(d=>d.id===result.navigation)){entry.nav=result.navigation;entry.label=destinations.find(d=>d.id===result.navigation).label}if(actions.some(a=>a[1]===result.request)){draft={type:result.request,raw:q};for(const k of ['from','to','dutyDate','hours','amount','reason','leaveType'])draft[k]=typeof result[k]==='string'?result[k]:'';entry.action=result.request}messages.push(entry)}catch(error){if(employee===self()){if(messages.at(-1)?.text==='Thinking…')messages.pop();messages.push({who:'assistant',text:error.message+' No request was submitted. You can still use the portal forms.'})}}finally{aiBusy=false;if(employee===self())open()}}
window.DemoAssistant={dismiss(){paint()},open,references,navigate,access(){modal('Assistant access',`<p><strong>Selected demo role: ${esc(role)}</strong></p><p>You can ask about your own sample leave, requests and pay (PSU employees), portal guidance, and professional reporting relationships.</p><p>Other employees’ salary, attendance, claims, leave balances and confidential personal records are restricted for all assistant roles. Supervisor reporting access does not include private team records.</p><p>Chat cannot grant new access or approve requests. HR/Payroll cross-employee access needs a production identity and permissions backend.</p><div class="callout">This is a browser-local demo. Role switching and employee context are not production authentication.</div>`,btn('Close',"$('#dialog').close()"))},close:paint,ask,send(e){e.preventDefault();ask(root.querySelector('#askInput').value)},action(type){sync();if(!actions.some(x=>x[1]===type))return;const d=draft?.type===type?draft:extractDraft('',type);paint();requestForm(type);const form=document.querySelector('#requestform');for(const key of ['from','to','dutyDate','hours','reason','amount']){const field=form.elements.namedItem(key);if(field)field.value=d[key]||''}if(type==='Leave'){if(d.leaveType)chooseLeaveType(d.leaveType);refreshLeaveSummary()}const note=document.createElement('div');note.className='callout';note.textContent='Assistant draft — review employee, dates, type, hours and reason. Nothing has been submitted. Submit request applies through the existing workflow.';form.prepend(note)}};
// Re-check persona on any portal render; do not share conversations across roles.
const observer=new MutationObserver(()=>{if(owner!==self()||signedOut){messages=[];owner=self();if(signedOut)root.innerHTML='';else paint()}});observer.observe(document.querySelector('#app'),{childList:true});paint();})();
